#!/usr/bin/env node
// Generates TypeScript types for the OpenAPI specs of every service listed in
// `contracts.config.json` -> `services`. Output lands in
// `src/contracts/types/<service-name>.ts`. Each file is generated by
// `openapi-typescript` and prefixed with an explicit auto-generated banner so
// the file is never edited by hand.
//
// Run via `pnpm contracts:generate`. The script is a hard error if any spec is
// missing — it composes with `pnpm contracts:check` for the canonical layout
// check.

import fs from "node:fs";
import path from "node:path";
import { fileURLToPath, pathToFileURL } from "node:url";
import openapiTS, { astToString } from "openapi-typescript";

const here = path.dirname(fileURLToPath(import.meta.url));
const repoRoot = path.resolve(here, "..");
const configPath = path.join(repoRoot, "contracts.config.json");

function fail(message) {
  console.error(`[contracts:generate] ${message}`);
  process.exit(1);
}

if (!fs.existsSync(configPath)) {
  fail(`config not found: ${configPath}`);
}

const config = JSON.parse(fs.readFileSync(configPath, "utf8"));
const contractsPath = path.resolve(repoRoot, config.path);

if (!fs.existsSync(contractsPath)) {
  fail(
    `canonical contracts path not found: ${contractsPath} — run \`pnpm contracts:check\` first`,
  );
}

if (!Array.isArray(config.services) || config.services.length === 0) {
  fail(
    `contracts.config.json must define a non-empty "services" array`,
  );
}

const outputDir = path.join(repoRoot, "src/contracts/types");
fs.mkdirSync(outputDir, { recursive: true });

const banner = (specRelativePath) =>
  `/* AUTO-GENERATED FILE — DO NOT EDIT.\n` +
  ` * Generated by \`pnpm contracts:generate\` from\n` +
  ` *   ${specRelativePath}\n` +
  ` * via openapi-typescript. Edit the canonical OpenAPI spec in the\n` +
  ` * backend monorepo instead and re-run \`pnpm contracts:generate\`.\n` +
  ` */\n\n`;

for (const service of config.services) {
  const specPath = path.join(contractsPath, service.openapi);
  if (!fs.existsSync(specPath)) {
    fail(`spec missing for service "${service.name}": ${specPath}`);
  }

  console.log(`[contracts:generate] ${service.name} <- ${service.openapi}`);
  const ast = await openapiTS(pathToFileURL(specPath));
  const body = astToString(ast);

  const outPath = path.join(outputDir, `${service.name}.ts`);
  fs.writeFileSync(
    outPath,
    banner(`${path.basename(contractsPath)}/${service.openapi}`) + body,
  );
}

console.log(`[contracts:generate] wrote ${config.services.length} client types to ${outputDir}`);
